// Generate embeddings:
query_vec = embed_model.encode("What is machine learning?")
// [0.23, -0.45, 0.78, ...] (1536 dimensions)

doc1_vec = embed_model.encode("ML is a subset of AI")
doc2_vec = embed_model.encode("Pizza recipe ingredients")

// Compute similarity (cosine):
sim1 = cosine_similarity(query_vec, doc1_vec)  // 0.87 (high similarity)
sim2 = cosine_similarity(query_vec, doc2_vec)  // 0.12 (low similarity)
